### ① Complete Elasticsearch Hybrid Pipeline

```python
from elasticsearch import Elasticsearch
import numpy as np
from sentence_transformers import SentenceTransformer

es = Elasticsearch("http://localhost:9200")
model = SentenceTransformer("all-MiniLM-L6-v2")  # 384d embeddings

# ── 1. Index with both BM25 and dense fields ─────────────────
def create_hybrid_index(index_name: str = "hybrid_docs"):
    if es.indices.exists(index=index_name):
        es.indices.delete(index=index_name)

    es.indices.create(index=index_name, body={
        "settings": {
            "number_of_shards": 1,
            "similarity": {"default": {"type": "BM25", "k1": 1.5, "b": 0.75}}
        },
        "mappings": {
            "properties": {
                "content": {
                    "type": "text",
                    "analyzer": "standard"
                },
                "embedding": {
                    "type": "dense_vector",
                    "dims": 384,
                    "index": True,
                    "similarity": "cosine"
                }
            }
        }
    })

def index_documents(docs: list[str], index_name: str = "hybrid_docs"):
    """Index documents with both text and embedding."""
    embeddings = model.encode(docs, batch_size=32, show_progress_bar=True)

    actions = [
        {
            "_index": index_name,
            "_id": str(i),
            "_source": {
                "content": doc,
                "embedding": embedding.tolist(),
            }
        }
        for i, (doc, embedding) in enumerate(zip(docs, embeddings))
    ]

    from elasticsearch import helpers
    helpers.bulk(es, actions)
    es.indices.refresh(index=index_name)

# ── 2. Hybrid Query ──────────────────────────────────────────
def hybrid_search_es(query: str, index_name: str = "hybrid_docs",
                     top_k: int = 10, alpha: float = 0.5):
    """
    Two-phase hybrid: BM25 + kNN via ES 8.x combined query.
    """
    query_embedding = model.encode(query)

    # Elasticsearch 8.x: built-in hybrid via knn + query
    result = es.search(
        index=index_name,
        body={
            "knn": {
                "field": "embedding",
                "query_vector": query_embedding.tolist(),
                "k": top_k * 2,
                "num_candidates": top_k * 10,
                "boost": alpha,  # weight for dense
            },
            "query": {
                "match": {
                    "content": {
                        "query": query,
                        "boost": 1 - alpha  # weight for BM25
                    }
                }
            },
            "size": top_k,
            "rank": {
                "rrf": {"window_size": 100, "rank_constant": 60}
            }
        }
    )

    return [
        {"id": hit["_id"], "score": hit["_score"],
         "content": hit["_source"]["content"]}
        for hit in result["hits"]["hits"]
    ]

# ── 3. Manual hybrid (for ES versions without built-in RRF) ─
def hybrid_search_manual(query: str, index_name: str,
                           top_k: int = 10, k_rrf: int = 60):
    """Manual hybrid: separate BM25 and kNN searches, then RRF."""
    query_embedding = model.encode(query)

    # BM25 search
    bm25_resp = es.search(
        index=index_name,
        body={"query": {"match": {"content": query}}, "size": top_k * 2}
    )
    bm25_ids = [h["_id"] for h in bm25_resp["hits"]["hits"]]

    # Dense kNN search
    dense_resp = es.search(
        index=index_name,
        body={
            "knn": {
                "field": "embedding",
                "query_vector": query_embedding.tolist(),
                "k": top_k * 2,
                "num_candidates": top_k * 10,
            },
            "size": top_k * 2,
        }
    )
    dense_ids = [h["_id"] for h in dense_resp["hits"]["hits"]]

    # RRF fusion
    hybrid_ranked = reciprocal_rank_fusion([bm25_ids, dense_ids], k=k_rrf)
    top_ids = [doc_id for doc_id, _ in hybrid_ranked[:top_k]]

    # Fetch full documents for top-k
    docs = es.mget(index=index_name, ids=top_ids)
    return [(doc["_id"], doc["_source"]["content"])
            for doc in docs["docs"] if doc["found"]]
